def replace_question_marks(s):
    n = len(s)
    if n % 2 != 0:
        return ":("

    open_needed = n // 2
    close_needed = n // 2

    for char in s:
        if char == '(':
            open_needed -= 1
        elif char == ')':
            close_needed -= 1

    if open_needed < 0 or close_needed < 0:
        return ":("

    balance = 0
    for i in range(n):
        if s[i] == '(':
            balance += 1
        elif s[i] == ')':
            balance -= 1
        elif s[i] == '?':
            if open_needed > 0:
                s = s[:i] + '(' + s[i+1:]
                balance += 1
                open_needed -= 1
            else:
                s = s[:i] + ')' + s[i+1:]
                balance -= 1

        if balance < 0 or (i < n - 1 and balance == 0):
            return ":("

    if balance != 0:
        return ":("

    return s

